select pbh.id as bomHistoryId, pbh.bom_version as bomVersion, pbs.parent_sku_id as parentSkuId, pbs.parent_sku_no as parentSkuNo, pbs.sku_id as skuId, pbs.sku_no as skuNo, pbi.bom_version as thisBomVersion, pbi.type AS type, pbs.quantity as quantity, pp.product_length as productLength, pp.product_width as productWidth, pp.product_height as productHeight, pd.name as skuName, pd.unit_name as unitName from product_bom_history pbh left join product_bom_sku_history pbs on pbh.id = pbs.bom_history_id and pbs.is_deleted = false left join product_detail pd on pbs.sku_id = pd.id and pd.is_deleted = false left join product_bom_info pbi on pbi.is_deleted = false and pbh.bom_id = pbi.id left join product_pack pp on pp.sku_id = pbs.sku_id
pbh.is_deleted = false and pbi.state = 4 and pbi.id in ( select distinct bom_id from product_bom_sku where is_deleted = false and parent_sku_id in
#{item}
